#include <iostream>
#include <fstream>
#include <string>
using namespace std;

int countName(string key) {
    ifstream in("students.txt");
    if (!in) {
        return -1;
    }
    int roll;
    string name;
    double marks;
    int matches = 0;
    while (in >> roll >> name >> marks) {
        if (name == key) {
            cout << "  roll " << roll << ": " << marks << endl;
            matches++;
        }
    }
    in.close();
    return matches;
}

int main() {
    ofstream out("students.txt");
    out << "101 Ali 78" << endl;
    out << "102 Sana 91" << endl;
    out << "103 Usman 66" << endl;
    out << "104 Sana 55" << endl;
    out.close();

    string names[2] = {"Sana", "Zara"};
    for (int i = 0; i < 2; i++) {
        cout << "Searching " << names[i] << ":" << endl;
        int n = countName(names[i]);
        if (n == 0) {
            cout << "  " << names[i] << " not found" << endl;
        } else {
            cout << "  " << names[i] << " found " << n << " time(s)" << endl;
        }
    }
    return 0;
}

#include <iostream>
#include <fstream>
#include <string>
using namespace std;

struct Student {
    int roll;
    string name;
    double marks;
};

void saveAll(Student s[], int n) {
    ofstream out("students.txt");
    for (int i = 0; i < n; i++) {
        out << s[i].roll << " " << s[i].name << " " << s[i].marks << endl;
    }
    out.close();
}

int loadAll(Student s[], int maxSize) {
    ifstream in("students.txt");
    int n = 0;
    while (n < maxSize && in >> s[n].roll >> s[n].name >> s[n].marks) {
        n++;
    }
    in.close();
    return n;
}

int main() {
    Student first[3] = { {101, "Ali", 78}, {102, "Sana", 91}, {103, "Usman", 66} };
    saveAll(first, 3);

    Student list[10];
    int n = loadAll(list, 10);
    cout << "Loaded " << n << " records" << endl;

    int key = 102;
    bool found = false;
    for (int i = 0; i < n; i++) {
        if (list[i].roll == key) {
            list[i].marks = 95;
            found = true;
        }
    }
    if (found) {
        saveAll(list, n);
    } else {
        cout << "Roll " << key << " not found" << endl;
    }

    Student check[10];
    int m = loadAll(check, 10);
    for (int i = 0; i < m; i++) {
        cout << check[i].roll << " " << check[i].name << " " << check[i].marks << endl;
    }
    return 0;
}

