#include <iostream>
#include <fstream>
#include <string>
using namespace std;
int main() {
    ofstream out("items.txt");
    out << "1 Pen 20" << endl << "2 Book 150" << endl << "3 Pen 25" << endl;
    out.close();
    ifstream in("items.txt");
    if (!in) { cout << "File not found!" << endl; return 1; }
    int id, count = 0;
    string name;
    double price, total = 0;
    while (in >> id >> name >> price) {
        if (name == "Pen") {
            count++;
            total += price;
        }
    }
    in.close();
    cout << "Pen: " << count << " time(s), total " << total << endl;
    return 0;
}
